def doublings(start, goal):
    count = 0
    while start < goal:
        start = start * 2
        count = count + 1
    return count

Lists#5:
def above_average(nums):
    if not nums:
        return []
    avg = sum(nums) / len(nums)
    return [x for x in nums if x > avg]

Dictionaries#5:
def word_counts(text):
    counts = {}
    for w in text.lower().split():
        counts[w] = counts.get(w, 0) + 1
    return counts

