Functions working together#3:
def fair_chance(odds):
    return -odds / (-odds + 100) if odds < 0 else 100 / (odds + 100)

def no_vig(a, b):
    x, y = fair_chance(a), fair_chance(b)
    return (round(x / (x + y), 3), round(y / (x + y), 3))

